  switch (method) {
    case "initialize":
      return respond(id, { result: {
        protocolVersion: supportedVersions.has(params?.protocolVersion) ? params.protocolVersion : "2025-11-25",
        capabilities: { tools: {} },
        serverInfo: { name: profile.name, version: "0.1.0" },
      } });
    case "ping":
      return respond(id, { result: {} });
    case "tools/list":
      return respond(id, { result: { tools } });
